import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The reference transferOwnership would set owner to address(1)
        // The buggy version reverts when newOwner != address(0)
        // We need to catch the revert to test the observable effect

        address alice = address(1);

        // The owner is initially the deployer (this test contract)
        // Try to transfer ownership to alice
        bool ok;
        try c.transferOwnership(alice) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, it should succeed (ok = true)
        // In the buggy version, it should fail (ok = false)
        // But the assertion is about the observable state:
        // If it succeeded, owner should be alice; if it failed, owner should remain the test contract.
        // Since we don't have a direct public getter for owner, we use the onlyOwner modifier behavior:
        // We can call finishDistribution which requires onlyOwner.
        // If transferOwnership succeeded, then only alice can call finishDistribution.
        // If it reverted, then the test contract is still owner.

        // Try to call finishDistribution from alice
        vm.prank(alice);
        bool ok2;
        try c.finishDistribution() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // In the reference, transferOwnership succeeded => alice is owner => finishDistribution succeeds => ok2 = true
        // In the buggy version, transferOwnership reverted => test contract is still owner => alice cannot call finishDistribution => ok2 = false
        assertTrue(ok2);
    }
}

